'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const subj=id=>ALL_SUBJECTS.find(s=>s.id===id);
const lesson=id=>ALL_LESSONS.find(l=>l.id===id);
let storeAvailable=true, saved={library:[],done:[],known:[],start:''};
try{const raw=JSON.parse(localStorage.getItem('medico-device-study')||'null');if(raw&&typeof raw==='object'){saved.library=Array.isArray(raw.library)?raw.library.filter(id=>subj(id)):[];saved.done=Array.isArray(raw.done)?raw.done.filter(n=>Number.isInteger(n)&&n>=1&&n<=180):[];saved.known=Array.isArray(raw.known)?raw.known.filter(id=>lesson(id)):[];saved.start=/^\d{4}-\d{2}-\d{2}$/.test(raw.start||'')?raw.start:'';}}catch{storeAvailable=false;}
let phase='All subjects',query='',planPage=0,planFilter='all',cardSubject='all',cardIndex=0,cardFlipped=false,cardUnknown=false,mapSubject='physiology',mapSelected=0,diagramType='circulation',dialogLesson=null,dialogTab='learn',quizAnswered=false,returnFocus=null,toastTimer;
const main=$('#main');
function save(){try{localStorage.setItem('medico-device-study',JSON.stringify(saved));}catch{storeAvailable=false;toast('Storage is unavailable. Your changes will last for this visit only.');}updateLibrary();}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
function updateLibrary(){$('#library-count').textContent=saved.library.length;}
function navigate(hash){if(location.hash===hash)render();else location.hash=hash;}
function options(current,includeAll=true){return `${includeAll?`<option value="all" ${current==='all'?'selected':''}>All subjects</option>`:''}${ALL_SUBJECTS.map(s=>`<option value="${s.id}" ${current===s.id?'selected':''}>${s.name}</option>`).join('')}`;}
function courseCard(s){const liked=saved.library.includes(s.id);return `<article class="course"><div class="course-cover" style="--cover:${s.color};--coverInk:${s.ink}"><div class="cover-top"><span class="pill">${s.phase}</span><button class="bookmark" data-action="bookmark" data-id="${s.id}" aria-label="${liked?'Remove':'Save'} ${s.name} ${liked?'from':'to'} library" aria-pressed="${liked}">${liked?'✓':'+'}</button></div><div class="cover-title">${s.cover||'Start with the essentials.'}</div><div class="mini-diagram" aria-label="${(s.flow||['Basics','Concepts','Confidence']).join(' to ')}">${(s.flow||['Basics','Concepts','Confidence']).map((x,i)=>`${i?'<i aria-hidden="true">→</i>':''}<span>${x}</span>`).join('')}</div></div><div class="course-body"><h3><a href="#subject/${s.id}">${s.name}</a></h3><p>${s.tagline}</p><div class="course-meta"><span>${s.lessons.length} concept lessons</span><span>◈ Visual map</span><span>▱ Recall cards</span></div><div class="course-bottom"><strong>Free to explore</strong><button data-action="subject" data-id="${s.id}">View collection</button></div></div></article>`;}
function catalog(){main.innerHTML=`<section class="hero"><div><span class="eyebrow">YOUR NEXT CHAPTER IN MEDICINE</span><h1>Big concepts.<br><em>Small, daily steps.</em></h1><p>Your visual study library for NEET PG. Explore the subjects, connect the concepts, and build understanding one day at a time.</p><div class="buttons"><a class="btn" href="#plan">Build my study rhythm</a><a class="btn secondary" href="#subject/foundation">New to medicine?</a></div><p class="fine">19 subjects · Beginner-friendly foundations · Free study collections</p></div><div class="visual-preview"><div class="preview-top"><span>A CONCEPT, CONNECTED</span><span class="pill">Physiology / 01</span></div><div class="circuit"><button class="node blue" data-action="circulation" data-id="0"><strong>Right heart</strong><span>To the lungs →</span></button><button class="node blue" data-action="circulation" data-id="1"><strong>Lungs</strong><span>Pick up oxygen ↓</span></button><button class="node oxygen" data-action="circulation" data-id="3"><strong>Body tissues</strong><span>Use oxygen ↑</span></button><button class="node oxygen" data-action="circulation" data-id="2"><strong>Left heart</strong><span>To the body ←</span></button></div><div class="flow-label">Two pumps. Two circuits. One continuous journey.</div><div class="preview-caption"><b>Understand the route, remember the reason.</b><a href="#maps" class="pill">Explore diagram</a></div></div></section><section class="stats" aria-label="Library contents"><div class="stat"><strong>19</strong><span>medical<br>subjects</span></div><div class="stat"><strong>180</strong><span>days of<br>guided study</span></div><div class="stat"><strong>128</strong><span>concept<br>lessons</span></div><div class="stat"><strong>01</strong><span>clear place<br>to begin</span></div></section><section id="collections"><div class="section-title"><div><span class="eyebrow">THE SUBJECT LIBRARY</span><h2>Find your next “aha” moment.</h2><p>Start with a subject. Leave with connections.</p></div><label class="search"><span aria-hidden="true">⌕</span><span class="sr-only">Search subjects and topics</span><input id="subject-search" type="search" placeholder="Search subjects or topics…" value="${esc(query)}"></label></div><div class="filters" role="group" aria-label="Filter subjects">${['All subjects','Pre-clinical','Para-clinical','Clinical'].map(p=>`<button class="filter ${phase===p?'active':''}" data-action="filter" data-id="${p}" aria-pressed="${phase===p}">${p}${p==='All subjects'?' · 19':''}</button>`).join('')}</div><div id="course-results" class="grid"></div><p id="result-count" class="fine" aria-live="polite"></p></section><section class="foundation-banner"><div><span class="eyebrow">NO MEDICAL BACKGROUND? START HERE.</span><h3>Before the syllabus, meet the basics.</h3><p>14 gentle lessons in cells, body systems, medical words and how to learn them.</p></div><a href="#subject/foundation" class="btn secondary">Explore the foundation course</a></section>`;renderCourses();}
function renderCourses(){const q=query.trim().toLowerCase();const matches=SUBJECTS.filter(s=>(phase==='All subjects'||s.phase===phase)&&`${s.name} ${s.scope} ${s.lessons.map(l=>`${l.title} ${l.simple} ${l.detail.join(' ')}`).join(' ')}`.toLowerCase().includes(q));$('#course-results').innerHTML=matches.length?matches.map(courseCard).join(''):'<div class="empty"><h3>No matching subjects</h3><p>Try “heart”, “blood”, “nerve” or clear your search.</p><button class="btn secondary" data-action="clear-search">Clear filters</button></div>';$('#result-count').textContent=`${matches.length} of 19 subject collections shown. Each collection includes concise notes and a broader topic checklist.`;}
function library(){main.innerHTML=`<div class="page-head"><span class="eyebrow">YOUR COLLECTION</span><h1>My library</h1><p>Keep the subjects you want to return to. Saved on this device only.</p></div><div class="grid">${saved.library.length?saved.library.map(id=>courseCard(subj(id))).join(''):'<div class="empty"><h2>A little room for your next big idea.</h2><p>Save a subject using the + button on its card.</p><a href="#catalog" class="btn">Explore subjects</a></div>'}</div>`;}
function subjectPage(id){const s=subj(id);if(!s)return notFound();const firstDay=DAYS.find(d=>d.subject===id)?.day;main.innerHTML=`<div class="page-head"><a class="eyebrow" href="#catalog">SUBJECT LIBRARY / ${s.phase.toUpperCase()}</a><h1>${s.name}</h1><p>${s.tagline} Begin with an everyday explanation, then connect it to the medical terminology.</p><div class="metric-line"><span>${s.lessons.length} lessons</span><span>${s.lessons.length} recall cards</span><span>${id==='foundation'?'Days 1–14':`Days ${firstDay}–${firstDay+7}`} in the study plan</span><span>Free access</span></div><div class="buttons"><button class="btn" data-action="lesson" data-id="${s.lessons[0].id}">Start learning</button><button class="btn secondary" data-action="bookmark" data-id="${id}" aria-pressed="${saved.library.includes(id)}">${saved.library.includes(id)?'✓ Saved in library':'+ Save to library'}</button><button class="btn ghost" data-action="subject-cards" data-id="${id}">Practice flashcards</button></div></div><div class="split"><aside class="panel side-panel"><span class="eyebrow">THE BIG PICTURE</span><h3>${s.name} topic checklist</h3><p class="muted">Use alongside the detailed NMC curriculum.</p><ul class="muted">${s.scope.split(';').map(t=>`<li>${t.trim()}</li>`).join('')}</ul><button class="btn secondary" data-action="subject-map" data-id="${id}">Open concept map</button></aside><section class="panel"><h2>Your learning path</h2><div class="lesson-list">${s.lessons.map((l,i)=>`<div class="lesson-tile"><span class="lesson-num">${String(i+1).padStart(2,'0')}</span><div><h3>${l.title}</h3><p>${l.simple}</p><span class="content-pill">Explain · Connect · Recall</span></div><button class="btn secondary" data-action="lesson" data-id="${l.id}">Open lesson</button></div>`).join('')}</div><div class="notice">These are concise introductory and revision notes. The topic checklist shows broader syllabus areas that require additional textbook reading and clinical study; it is not a claim of exhaustive NEET PG preparation.</div></section></div>`;}
function dateForDay(n){if(!saved.start)return '';const d=new Date(`${saved.start}T12:00:00`);if(Number.isNaN(d.getTime()))return '';d.setDate(d.getDate()+n-1);return d.toLocaleDateString('en-IN',{day:'numeric',month:'short'});}
function filteredDays(){return DAYS.filter(d=>planFilter==='all'||(planFilter==='revision'?d.type==='revision':planFilter==='incomplete'?!saved.done.includes(d.day):d.subject===planFilter));}
function plan(){main.innerHTML=`<div class="page-head"><span class="eyebrow">A LITTLE PROGRESS, EVERY DAY</span><h1>Your 180-day study rhythm.</h1><p>14 foundation days, 152 subject-study and review days, then 14 integrated revision days. Start with 90 minutes a day and add textbook and question-bank time as needed.</p></div><div class="split"><aside class="panel side-panel"><span class="eyebrow">YOUR PLAN</span><h3>${saved.done.length} / 180 days complete</h3><div class="progress-track" role="progressbar" aria-label="Study plan completion" aria-valuenow="${saved.done.length}" aria-valuemin="0" aria-valuemax="180"><i style="width:${saved.done.length/1.8}%"></i></div><label for="start-date">Start date (optional)</label><input type="date" id="start-date" value="${saved.start}"><label for="plan-filter">Jump to a collection</label><select id="plan-filter"><option value="all">All 180 days</option><option value="incomplete" ${planFilter==='incomplete'?'selected':''}>Incomplete days</option>${options(planFilter,false)}<option value="revision" ${planFilter==='revision'?'selected':''}>Integrated revision</option></select><h3 style="margin-top:24px">A simple daily routine</h3><p class="muted">30 min · Understand the concept<br>20 min · Draw and explain it<br>20 min · Retrieve without looking<br>20 min · Read deeper and revisit</p><p class="fine">Your start date and completion marks stay on this device${storeAvailable?'.':' for this visit; storage is unavailable.'} This is a flexible study scaffold, not an exam-readiness guarantee.</p></aside><section><div id="plan-days" class="plan-list"></div><div id="plan-pager"></div></section></div>`;renderDays();}
function renderDays(){const ds=filteredDays();const pages=Math.max(1,Math.ceil(ds.length/10));planPage=Math.min(planPage,pages-1);const visible=ds.slice(planPage*10,planPage*10+10);$('#plan-days').innerHTML=visible.length?visible.map(d=>`<article class="day-row ${saved.done.includes(d.day)?'done':''}"><div class="day-number">DAY<strong>${String(d.day).padStart(2,'0')}</strong></div><div><span class="eyebrow" style="font-size:12px;letter-spacing:.7px">${d.subject==='revision'?'INTEGRATED REVISION':subj(d.subject).name} ${dateForDay(d.day)?'· '+dateForDay(d.day):''}</span><h3>${d.title}</h3><p>${d.type==='learn'?'Read · Draw · Recall':d.type==='map'?'Connect six concepts · Explain the links':d.type==='review'?'Retrieve six answers · Revisit weak concepts':'Compare subjects · Mixed retrieval · Review mistakes'} · 90 min suggested</p></div><div class="day-actions"><button class="btn secondary" data-action="day" data-id="${d.day}">Open day</button><button class="check" data-action="done" data-id="${d.day}" aria-label="Mark day ${d.day} ${saved.done.includes(d.day)?'incomplete':'complete'}" aria-pressed="${saved.done.includes(d.day)}">${saved.done.includes(d.day)?'✓':''}</button></div></article>`).join(''):'<div class="empty"><h3>All days complete</h3><p>Choose another collection or revisit your study notes.</p></div>';$('#plan-pager').innerHTML=`<div class="pager"><button class="btn secondary" data-action="plan-prev" ${planPage===0?'disabled':''}>Previous</button><span>${ds.length?`${planPage*10+1}–${Math.min(ds.length,(planPage+1)*10)} of ${ds.length}`:'0 days'}</span><button class="btn secondary" data-action="plan-next" ${planPage===pages-1?'disabled':''}>Next</button></div>`;}
function showDialog(content){returnFocus=document.activeElement;$('#lesson-content').innerHTML=content;$('#lesson-dialog').showModal();}
function closeDialog(){$('#lesson-dialog').close();dialogLesson=null;if(returnFocus?.isConnected)returnFocus.focus();}
function openDay(n){const d=DAYS[n-1];if(!d)return;const isLearn=d.type==='learn';const review=d.lessons.map(lesson);showDialog(`<div class="dialog-head"><div><span class="eyebrow">DAY ${n} · ${dateForDay(n)||'YOUR OWN PACE'}</span><h2 id="lesson-title">${d.title}</h2></div><button class="close" data-action="close" aria-label="Close study day">×</button></div><div class="dialog-body"><p>${isLearn?'Build understanding first, then check what you can remember without looking.':d.type==='map'?'Build a map of the collection. Explain what each branch contributes and where the ideas connect.':'Try each question before revealing its answer. Mark concepts to revisit, then return to the linked lesson.'}</p><div class="concept-grid"><div class="concept"><span class="eyebrow">01 / UNDERSTAND</span><p>${isLearn?'Read the plain-language explanation. Define three unfamiliar words.':'Review the subject map and recall its main branches.'}</p></div><div class="concept"><span class="eyebrow">02 / CONNECT</span><p>${isLearn?'Sketch the concept flow. Explain each link in one sentence.':'Choose two concepts and explain their relationship with an example.'}</p></div><div class="concept"><span class="eyebrow">03 / RETRIEVE</span><p>Answer without looking. Check your explanation, record mistakes and repeat missed items.</p></div></div>${review.map(l=>`<details ${isLearn?'open':''}><summary>${isLearn?l.title:l.q}</summary><p>${isLearn?l.simple:l.a}</p><p class="muted">${l.detail[0]}</p><button class="btn secondary" data-action="lesson" data-id="${l.id}">Study concept</button></details>`).join('')}<p class="fine">Read deeper: use the subject checklist and the reference sources to expand beyond these short notes. Choose a separate reviewed question bank for exam-level practice.</p><div class="buttons">${d.subject!=='revision'?`<button class="btn secondary" data-action="subject-map" data-id="${d.subject}">Open subject map</button>`:''}<button class="btn" data-action="day-complete" data-id="${n}">${saved.done.includes(n)?'Mark incomplete':'Mark day complete'}</button></div></div>`);}
function openLesson(id){const l=lesson(id);if(!l)return;dialogLesson=l;dialogTab='learn';quizAnswered=false;if($('#lesson-dialog').open){$('#lesson-content').innerHTML=lessonHtml();}else showDialog(lessonHtml());}
function lessonHtml(){const l=dialogLesson,s=subj(l.subject);return `<div class="dialog-head"><div><span class="eyebrow">${s.name} · CONCEPT ${s.lessons.indexOf(l)+1}</span><h2 id="lesson-title">${l.title}</h2></div><button class="close" data-action="close" aria-label="Close lesson">×</button></div><div class="dialog-body"><div class="tabs" role="group" aria-label="Lesson sections">${[['learn','Understand'],['visual','Connect'],['quiz','Recall']].map(([id,t])=>`<button aria-pressed="${dialogTab===id}" class="${dialogTab===id?'active':''}" data-action="lesson-tab" data-id="${id}">${t}</button>`).join('')}</div><section id="lesson-panel" aria-label="${dialogTab==='learn'?'Understand':dialogTab==='visual'?'Connect':'Recall'}">${lessonPanel()}</section></div>`;}
function lessonPanel(){const l=dialogLesson;if(dialogTab==='learn')return `<span class="eyebrow">IN EVERYDAY WORDS</span><p style="font-size:20px;line-height:1.7">${l.simple}</p><h3>Build the concept</h3>${l.detail.map((t,i)=>`<div class="lesson-tile"><span class="lesson-num">0${i+1}</span><p>${t}</p></div>`).join('')}<h3>Make it stick</h3><p class="muted">Close the notes and explain “${l.title.toLowerCase()}” to someone with no medical background. Use the concept flow to organize your explanation, then answer the recall question.</p><div class="buttons"><button class="btn" data-action="lesson-tab" data-id="visual">See the concept flow</button><button class="btn secondary" data-action="lesson-tab" data-id="quiz">Test my recall</button></div><p class="fine">Concise educational notes. For detailed study, expand each point with the linked subject checklist and reference texts.</p>`;if(dialogTab==='visual')return `<span class="eyebrow">CONCEPT FLOW · SIMPLIFIED RELATIONSHIPS</span><div class="lesson-flow">${l.flow.map((x,i)=>`${i?'<span class="flow-connector" aria-hidden="true">→</span>':''}<div class="flow-node"><b>0${i+1}</b>${x}</div>`).join('')}</div><p>${l.simple}</p><div class="notice">Try drawing this from memory. The links organize the concept; they are a simplified teaching model, not a complete biological pathway.</div><ul>${l.detail.map(t=>`<li>${t}</li>`).join('')}</ul><button class="btn" data-action="lesson-tab" data-id="quiz">Check my understanding</button>`;const other=subj(l.subject).lessons.filter(x=>x.id!==l.id).slice(0,2).map(x=>x.a);const answers=[l.a,...other].sort((a,b)=>a.localeCompare(b));return `<span class="eyebrow">ONE CONCEPT · ONE CHECK</span><h3>${l.q}</h3><div class="quiz-options">${answers.map((a,i)=>`<button class="quiz-option" data-action="quiz-answer" data-correct="${a===l.a}" data-id="${i}">${esc(a)}</button>`).join('')}</div><div id="quiz-feedback" class="feedback" aria-live="polite"></div><p class="fine">This is a basic concept check, not an official NEET PG question or exam-level mock.</p>`;}
function deck(){return ALL_LESSONS.filter(l=>(cardSubject==='all'||l.subject===cardSubject)&&(!cardUnknown||!saved.known.includes(l.id)));}
function flashcards(){main.innerHTML=`<div class="page-head"><span class="eyebrow">RECALL, DON'T JUST REREAD</span><h1>A little practice. A stronger memory.</h1><p>Think of your answer before turning the card. Set difficult concepts aside to revisit.</p></div><section class="flash-area"><div class="toolbar"><label class="sr-only" for="card-subject">Flashcard subject</label><select id="card-subject">${options(cardSubject)}</select><label style="font-size:14px"><input type="checkbox" id="card-unknown" ${cardUnknown?'checked':''}> Still learning only</label></div><div id="flash-content"></div><p class="fine">“Got it” is your own assessment, saved on this device. These cards are learning prompts, not an exam question bank.</p></section>`;renderFlash();}
function renderFlash(){const cards=deck();if(!cards.length){$('#flash-content').innerHTML='<div class="empty"><h2>You have reviewed this deck.</h2><p>Clear “Still learning only” to practice every card again.</p></div>';return;}cardIndex=(cardIndex+cards.length)%cards.length;const l=cards[cardIndex];$('#flash-content').innerHTML=`<div class="section-title"><span class="tag">${subj(l.subject).name}</span><span class="fine">Card ${cardIndex+1} of ${cards.length}</span></div><button class="flashcard ${cardFlipped?'back':''}" data-action="flip" aria-label="${cardFlipped?'Show question':'Reveal answer'}"><span class="eyebrow">${cardFlipped?'THE ANSWER':'PAUSE. THINK. RECALL.'}</span><h2>${cardFlipped?l.a:l.q}</h2><p class="fine">${cardFlipped?'Click to return to the question':'Click or press Enter to turn the card'}</p></button>${cardFlipped?`<p class="muted">${l.simple}</p>`:''}<div class="flash-controls"><button class="btn secondary" data-action="card-prev">Previous</button><div class="buttons"><button class="btn secondary" data-action="card-again" data-id="${l.id}">Still learning</button><button class="btn" data-action="card-known" data-id="${l.id}">Got it ✓</button></div><button class="btn secondary" data-action="card-next">Next</button></div><div style="text-align:center;margin-top:20px"><button class="btn ghost" data-action="lesson" data-id="${l.id}">Read this concept</button></div>`;}
const DIAGRAMS={
circulation:{title:'The circulation loop',intro:'Follow the blood through two linked circuits. Select a station to understand its job.',nodes:[['Right heart','Pumps to the lungs','The right atrium receives systemic venous blood. The right ventricle sends it through pulmonary arteries to the lungs. Arteries are named by direction away from the heart, not oxygen content.'],['Lungs','Exchange oxygen and carbon dioxide','Pulmonary capillaries lie beside alveoli. Oxygen enters blood and carbon dioxide leaves under normal conditions. Pulmonary veins return oxygen-rich blood to the left atrium.'],['Left heart','Pumps to the body','The left ventricle pumps into the aorta. The systemic circuit distributes oxygen and nutrients to tissues. The pulmonary and systemic circuits carry the same average flow in steady state.'],['Body tissues','Use oxygen and return blood','Systemic capillaries allow exchange with tissues. Venous blood returns toward the right atrium. Oxygen-poor blood is still red; blue is only a teaching color.']]},
feedback:{title:'Negative feedback, explained',intro:'A thermostat is a useful analogy. Select each step to follow the control loop.',nodes:[['Disturbance','A variable changes','A regulated variable, such as temperature, moves away from its usual range. Homeostasis is dynamic rather than perfectly fixed.'],['Sensor & control','Detect and compare','Sensors detect the change. A control system integrates the information and coordinates an appropriate response.'],['Effector','Act on the disturbance','Effectors carry out a response. With increased body temperature, sweating and changes in skin blood flow can help lose heat.'],['Correction','Reduce the original change','The response opposes the disturbance, so the drive for that response decreases as the variable returns toward its regulated range.']]},
nephron:{title:'A nephron in four jobs',intro:'Follow what happens to water and solutes. This is a functional schematic, not an anatomical drawing.',nodes:[['Filtration','Blood to tubular fluid','The glomerular barrier filters water and many small solutes while normally retaining blood cells and most proteins. Filtration is not the same as final urine output.'],['Reabsorption','Useful material returns','Tubular transport returns water and useful solutes to the circulation. Different nephron segments have different transport properties.'],['Secretion','More material enters the tubule','Tubular secretion moves selected substances from blood into tubular fluid. It contributes to removal of some drugs, acids and ions.'],['Excretion','The final urinary output','For a substance: excretion = filtration − reabsorption + secretion. Hormones and physiological conditions influence the final balance.']]},
synapse:{title:'How a chemical synapse works',intro:'Connect an electrical signal to a chemical message and then to a new response.',nodes:[['Action potential','Signal reaches the terminal','Depolarization at the presynaptic terminal opens voltage-gated calcium channels.'],['Calcium entry','Release is triggered','Calcium entry promotes fusion of neurotransmitter-containing vesicles with the presynaptic membrane.'],['Receptor binding','A message crosses the gap','Neurotransmitter diffuses across the synaptic cleft and binds receptors. The response depends on receptor and cell type.'],['Signal ends','Prepare for the next message','Transmitter action is limited by mechanisms such as reuptake, enzymatic breakdown or diffusion, depending on the transmitter.']]},
hemostasis:{title:'From vessel injury to stable clot',intro:'Hemostasis has overlapping components. This sequence is a simplified learning guide.',nodes:[['Vessel injury','Local vascular response','Vascular injury exposes subendothelial material and triggers local responses. Endothelial integrity normally helps regulate clotting.'],['Platelet plug','Primary hemostasis','Platelets adhere, activate and aggregate. Von Willebrand factor assists platelet adhesion, particularly under high shear.'],['Fibrin formation','Secondary hemostasis','Coagulation generates thrombin, which converts fibrinogen to fibrin. Fibrin helps stabilize the platelet plug.'],['Regulation & repair','Clot is limited and remodeled','Anticoagulant pathways limit clotting. Fibrinolysis breaks down fibrin as repair progresses; these processes are coordinated rather than strictly sequential.']]}
};
function maps(){const s=subj(mapSubject)||SUBJECTS[1];main.innerHTML=`<div class="page-head"><span class="eyebrow">LESS MEMORIZING. MORE CONNECTING.</span><h1>Your visual atlas.</h1><p>Follow a process step by step, or zoom out to see how the ideas in a subject fit together.</p></div><div class="section-title"><h2>Trace a mechanism</h2></div><label class="sr-only" for="diagram-select">Choose a diagram</label><select id="diagram-select" class="diagram-selector">${Object.entries(DIAGRAMS).map(([id,d])=>`<option value="${id}" ${id===diagramType?'selected':''}>${d.title}</option>`).join('')}</select><div id="diagram-view"></div><div class="section-title" style="margin-top:45px"><div><h2>A subject, at a glance.</h2><p>Select a branch to explore its core ideas.</p></div><label><span class="sr-only">Choose mind map subject</span><select id="map-select">${options(s.id,false)}</select></label></div><div class="map-wrap"><section class="panel"><div class="map-center">${s.name}</div><div class="map-nodes">${s.lessons.map((l,i)=>`<button class="map-node ${i===mapSelected?'selected':''}" data-action="map-node" data-id="${i}" aria-pressed="${i===mapSelected}">${l.title}<small>Concept ${String(i+1).padStart(2,'0')}</small></button>`).join('')}</div></section><aside class="panel" id="map-detail"></aside></div>`;renderDiagram(0);renderMapDetail();}
function renderDiagram(index){const d=DIAGRAMS[diagramType];$('#diagram-view').innerHTML=`<section class="diagram-stage"><h3>${d.title}</h3><p class="muted">${d.intro}</p><div class="diagram-steps" style="margin-top:22px">${d.nodes.map((n,i)=>`<button class="diagram-step" data-action="diagram-node" data-id="${i}" aria-pressed="${index===i}" style="${index===i?'background:#d9ece0;border-color:#096e61':''}"><span class="eyebrow">0${i+1}${i<3?' →':''}</span><strong>${n[0]}</strong><small>${n[1]}</small></button>`).join('')}</div><div class="diagram-detail" aria-live="polite"><strong>${d.nodes[index][0]}</strong><p class="muted">${d.nodes[index][2]}</p></div><p class="fine">Simplified teaching schematic. Read the explanation with the flow; the diagram omits many regulatory details.</p></section>`;}
function renderMapDetail(){const s=subj(mapSubject),l=s.lessons[mapSelected]||s.lessons[0];$('#map-detail').innerHTML=`<span class="eyebrow">EXPLORE A CONNECTION</span><h3>${l.title}</h3><p class="muted">${l.simple}</p><ul style="padding-left:18px;font-size:14px">${l.detail.map(t=>`<li style="margin-top:12px">${t}</li>`).join('')}</ul><button class="btn secondary" data-action="lesson" data-id="${l.id}">Open lesson</button>`;}
function sources(){main.innerHTML=`<article class="reading"><div class="page-head"><span class="eyebrow">READ WITH CONTEXT</span><h1>Sources & content scope</h1><p>A useful starting point is clear about what it covers.</p></div><h2>What is included</h2><p>Medico contains 19 medical subject collections, 14 beginner foundation lessons, 114 subject concept lessons, 128 recall cards, 20 subject maps and 5 interactive process diagrams. The 180-day plan combines these with subject review and integrated revision.</p><h2>What “syllabus coverage” means here</h2><p>The collections organize the major medical subjects commonly used for NEET PG preparation. Their topic checklists are broad study outlines. The concise lessons introduce and revise selected concepts; they do not cover every competency, disease, investigation, treatment or exam detail. This is not an official NBEMS course, a complete medical textbook, a clinically reviewed question bank or a guarantee of exam readiness.</p><p>Use the NMC competency document for detailed curriculum requirements and current NBEMS information for examination rules. Add standard textbooks, supervised clinical learning and a reviewed question bank to your plan.</p><h2>Reference library</h2><ul class="source-list"><li><a href="https://www.nmc.org.in/wp-content/uploads/2026/02/12bCompetencyBasedMedicalEducationCBMECurriculum12092024.pdf" target="_blank" rel="noopener">NMC — Competency Based Medical Education Curriculum 2024</a><br><span class="muted">Official curriculum reference for detailed subject competencies.</span></li><li><a href="https://www.natboard.edu.in/" target="_blank" rel="noopener">NBEMS — National Board of Examinations in Medical Sciences</a><br><span class="muted">Use the current NEET PG information bulletin for eligibility, examination scheme, dates and notices.</span></li><li><a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/1-5-homeostasis" target="_blank" rel="noopener">OpenStax — Anatomy and Physiology 2e: Homeostasis</a><br><span class="muted">Further reading on the beginner feedback concept; browse the textbook for foundational anatomy and physiology.</span></li><li><a href="https://www.msdmanuals.com/professional/endocrine-and-metabolic-disorders/diabetes-mellitus-and-hypoglycemia/overview-of-diabetes-mellitus" target="_blank" rel="noopener">MSD Manual Professional — Overview of Diabetes Mellitus</a><br><span class="muted">Further reading on glucose regulation and diabetes. Clinical references must be consulted in context.</span></li></ul><p class="fine">Reference links checked during creation on 9 October 2026. Notes are original, concise educational summaries and have not received clinician editorial review. These references are further reading and curriculum context, not a claim of sentence-by-sentence validation.</p><h2>Beginner access & exam eligibility</h2><p>Anyone can use the foundation lessons to learn medical concepts. NEET PG examination eligibility is different: NBEMS specifies recognized MBBS qualifications, registration and internship requirements, subject to the applicable information bulletin. Learning on this site does not establish eligibility or qualify someone to diagnose or treat patients.</p><h2>Your data & access</h2><p>All study collections are free. Saving a subject creates a local library bookmark, not a paid purchase. Your saved subjects, study start date, completion marks and self-rated cards are stored only in this browser when storage is available. There is no account synchronization or payment checkout. Clearing browser data removes this progress.</p></article>`;}
function notFound(){main.innerHTML='<div class="empty"><h1>This page is not in the library.</h1><a class="btn" href="#catalog">Explore subjects</a></div>';}
function render(){if($('#lesson-dialog').open)closeDialog();const route=(location.hash||'#catalog').slice(1);document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${route.split('/')[0]}`));if(route==='catalog')catalog();else if(route==='plan')plan();else if(route==='cards')flashcards();else if(route==='maps')maps();else if(route==='library')library();else if(route==='sources')sources();else if(route.startsWith('subject/'))subjectPage(route.split('/')[1]);else notFound();updateLibrary();window.scrollTo(0,0);}
function toggleDone(n){if(!Number.isInteger(n)||n<1||n>180)return;saved.done=saved.done.includes(n)?saved.done.filter(x=>x!==n):[...saved.done,n];save();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='library')navigate('#library');if(a==='subject')navigate(`#subject/${id}`);if(a==='bookmark'){saved.library=saved.library.includes(id)?saved.library.filter(x=>x!==id):[...saved.library,id];save();const scroll=window.scrollY;render();window.scrollTo(0,scroll);toast(saved.library.includes(id)?'Saved to your library on this device.':'Removed from your library.');}if(a==='filter'){phase=id;catalog();}if(a==='clear-search'){phase='All subjects';query='';catalog();}if(a==='lesson')openLesson(id);if(a==='close')closeDialog();if(a==='lesson-tab'){dialogTab=id;quizAnswered=false;$('#lesson-content').innerHTML=lessonHtml();}if(a==='quiz-answer'&&!quizAnswered){quizAnswered=true;const correct=b.dataset.correct==='true';document.querySelectorAll('.quiz-option').forEach(x=>{x.disabled=true;if(x.dataset.correct==='true')x.classList.add('correct');});if(!correct)b.classList.add('incorrect');$('#quiz-feedback').innerHTML=`<strong>${correct?'Correct.':'Revisit this one.'}</strong> ${dialogLesson.a}.<p>${dialogLesson.simple}</p><button class="btn secondary" data-action="lesson-tab" data-id="learn">Review explanation</button>`;}if(a==='day')openDay(Number(id));if(a==='done'){toggleDone(Number(id));const scroll=window.scrollY;plan();window.scrollTo(0,scroll);}if(a==='day-complete'){toggleDone(Number(id));closeDialog();if(location.hash==='#plan')plan();toast(saved.done.includes(Number(id))?`Day ${id} marked complete.`:`Day ${id} marked incomplete.`);}if(a==='plan-prev'){planPage=Math.max(0,planPage-1);renderDays();}if(a==='plan-next'){planPage++;renderDays();}if(a==='subject-cards'){cardSubject=id;cardIndex=0;cardFlipped=false;navigate('#cards');}if(a==='flip'){cardFlipped=!cardFlipped;renderFlash();}if(['card-next','card-prev','card-known','card-again'].includes(a)){if(a==='card-known'){if(!saved.known.includes(id))saved.known.push(id);save();if(!cardUnknown)cardIndex++;}else if(a==='card-again'){saved.known=saved.known.filter(x=>x!==id);save();cardIndex++;}else cardIndex+=a==='card-prev'?-1:1;cardFlipped=false;renderFlash();}if(a==='subject-map'){mapSubject=id;mapSelected=0;if($('#lesson-dialog').open)closeDialog();navigate('#maps');}if(a==='map-node'){mapSelected=Number(id);document.querySelectorAll('.map-node').forEach((n,i)=>{n.classList.toggle('selected',i===mapSelected);n.setAttribute('aria-pressed',i===mapSelected);});renderMapDetail();}if(a==='diagram-node')renderDiagram(Number(id));if(a==='circulation'){diagramType='circulation';navigate('#maps');setTimeout(()=>{if($('#diagram-view'))renderDiagram(Number(id));},0);}});
document.addEventListener('input',e=>{if(e.target.id==='subject-search'){query=e.target.value;renderCourses();}});
document.addEventListener('change',e=>{const id=e.target.id,v=e.target.value;if(id==='plan-filter'){planFilter=v;planPage=0;renderDays();}if(id==='start-date'){saved.start=v;save();renderDays();}if(id==='card-subject'){cardSubject=v;cardIndex=0;cardFlipped=false;renderFlash();}if(id==='card-unknown'){cardUnknown=e.target.checked;cardIndex=0;cardFlipped=false;renderFlash();}if(id==='map-select'){mapSubject=v;mapSelected=0;maps();}if(id==='diagram-select'){diagramType=v;renderDiagram(0);}});
$('#lesson-dialog').addEventListener('click',e=>{if(e.target===$('#lesson-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
$('#lesson-dialog').addEventListener('cancel',()=>{dialogLesson=null;});
window.addEventListener('hashchange',render);render();
// Optional WebMCP integration: mirrors existing visible navigation without marking work complete.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'get_study_outline',description:'Read the available medical subject collections and the 180-day plan outline.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({subjects:ALL_SUBJECTS.map(s=>({id:s.id,name:s.name,lessonCount:s.lessons.length})),days:DAYS.length,completedDays:saved.done.length})});register({name:'open_study_day',description:'Navigate to the plan and open a study day. Does not mark it complete.',inputSchema:{type:'object',properties:{day:{type:'integer',minimum:1,maximum:180}},required:['day'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!Number.isInteger(input.day)||input.day<1||input.day>180)throw new Error('day must be an integer from 1 to 180');if(location.hash!=='#plan'){location.hash='#plan';await new Promise(resolve=>window.addEventListener('hashchange',resolve,{once:true}));}else if($('#lesson-dialog').open)closeDialog();openDay(input.day);return{day:input.day,title:DAYS[input.day-1].title,completed:saved.done.includes(input.day)};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
